    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):

    def format_plane_eq(a, b, c, d):
        terms = []
        if a != 0:
            if a == 1: terms.append("x")
            elif a == -1: terms.append("-x")
            else: terms.append(f"{a}x")
        if b != 0:
            if b == 1: terms.append("y")
            elif b == -1: terms.append("-y")
            else: terms.append(f"{b}y")
        if c != 0:
            if c == 1: terms.append("z")
            elif c == -1: terms.append("-z")
            else: terms.append(f"{c}z")

        if not terms:
            lhs = "0"
        else:
            lhs = ' + '.join(terms)
            lhs = lhs.replace(' + -', ' - ')
        return f"{lhs} = {d}"

    for _ in range(200): # Retry limit
        a, b, c = rng.randint(-5, 5), rng.randint(-5, 5), rng.randint(-5, 5)
        if a == 0 and b == 0 and c == 0:
            continue
        norm_sq = a*a + b*b + c*c

        j = rng.choice([-3, -2, -1, 1, 2, 3])

        m, n, p, q = rng.randint(1, 5), rng.randint(1, 5), rng.randint(0, 5), rng.randint(0, 5)
        if m*m + n*n == p*p + q*q and m*p + n*q == 0 and m*q - n*p == 0:
            continue

        dx = m*m + n*n - p*p - q*q
        dy = 2 * (m*p + n*q)
        dz = 2 * (m*q - n*p)
        L = m*m + n*n + p*p + q*q

        val_dot_product = a*dx + b*dy + c*dz

        if j * (-j * norm_sq + val_dot_product) <= 0:
            continue

        if (dy*c - dz*b == 0) and (dz*a - dx*c == 0) and (dx*b - dy*a == 0):
            if not (dx==0 and dy==0 and dz==0):
                continue

        f1x, f1y, f1z = rng.randint(-10, 10), rng.randint(-10, 10), rng.randint(-10, 10)

        plane_val_f1 = a*f1x + b*f1y + c*f1z
        d = plane_val_f1 - j * norm_sq

        k = -2 * j
        f1px = f1x + a * k
        f1py = f1y + b * k
        f1pz = f1z + c * k

        f2x = f1px + dx
        f2y = f1py + dy
        f2z = f1pz + dz

        if f1x == f2x and f1y == f2y and f1z == f2z:
            continue

        val2 = a*f2x + b*f2y + c*f2z - d
        if val2 == 0:
            continue

        if L < 10 or L > 150:
            continue

        plane_eq = format_plane_eq(a, b, c, d)

        return {
            'f1x': f1x, 'f1y': f1y, 'f1z': f1z,
            'f2x': f2x, 'f2y': f2y, 'f2z': f2z,
            'a': a, 'b': b, 'c': c, 'd': d,
            'plane_eq': plane_eq
        }
    raise Exception("Failed to generate a valid problem instance")

        import math

def verifier(assign):
    f1x, f1y, f1z = assign['f1x'], assign['f1y'], assign['f1z']
    f2x, f2y, f2z = assign['f2x'], assign['f2y'], assign['f2z']
    a, b, c, d = assign['a'], assign['b'], assign['c'], assign['d']

    # The plane is ax + by + cz - d = 0
    # Check that foci are on the same side of the plane and not on the plane
    val1 = a * f1x + b * f1y + c * f1z - d
    val2 = a * f2x + b * f2y + c * f2z - d

    if val1 == 0 or val2 == 0:
        return False, None # A focus cannot be on the tangent plane
    if val1 * val2 < 0:
        return False, None # Foci must be on the same side of the tangent plane

    # Calculate the reflection of F1 across the plane
    norm_sq = a*a + b*b + c*c
    if norm_sq == 0:
        return False, None # Invalid plane equation

    k = -2 * val1 / norm_sq

    f1px = f1x + a * k
    f1py = f1y + b * k
    f1pz = f1z + c * k

    # The length of the major axis is the distance between the reflection F1' and F2
    dist_sq = (f2x - f1px)**2 + (f2y - f1py)**2 + (f2z - f1pz)**2

    # The generator ensures the answer is an integer.
    # We verify this, allowing for small floating point inaccuracies.
    answer = math.sqrt(dist_sq)
    if not math.isclose(answer, round(answer)):
        return False, None # Generated problem does not have an integer solution

    final_answer = int(round(answer))

    # Check for triviality
    if final_answer < 10:
        return False, None # Solution is too simple

    return True, final_answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

